class _UniffiFfiConverterString:
    @staticmethod
    def check_lower(value):
        if not isinstance(value, str):
            raise TypeError("argument must be str, not {}".format(type(value).__name__))
        return value

    @staticmethod
    def read(buf):
        size = buf.read_i32()
        if size < 0:
            raise InternalError("Unexpected negative string length")
        utf8_bytes = buf.read(size)
        return utf8_bytes.decode("utf-8")

    @staticmethod
    def write(value, buf):
        utf8_bytes = value.encode("utf-8")
        buf.write_i32(len(utf8_bytes))
        buf.write(utf8_bytes)

    @staticmethod
    def lift(buf):
        with buf.consume_with_stream() as stream:
            return stream.read(stream.remaining()).decode("utf-8")

    @staticmethod
    def lower(value):
        with _UniffiRustBuffer.alloc_with_builder() as builder:
            builder.write(value.encode("utf-8"))
            return builder.finalize()






class FfiProfile(enum.Enum):
    
    PUBLIC = 0
    
    HYBRID = 1
    
    SELF_HOSTED = 2
    
    LOCAL = 3
    
    SOVEREIGN = 4
    


class _UniffiFfiConverterTypeFfiProfile(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return FfiProfile.PUBLIC
        if variant == 2:
            return FfiProfile.HYBRID
        if variant == 3:
            return FfiProfile.SELF_HOSTED
        if variant == 4:
            return FfiProfile.LOCAL
        if variant == 5:
            return FfiProfile.SOVEREIGN
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == FfiProfile.PUBLIC:
            return
        if value == FfiProfile.HYBRID:
            return
        if value == FfiProfile.SELF_HOSTED:
            return
        if value == FfiProfile.LOCAL:
            return
        if value == FfiProfile.SOVEREIGN:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == FfiProfile.PUBLIC:
            buf.write_i32(1)
        if value == FfiProfile.HYBRID:
            buf.write_i32(2)
        if value == FfiProfile.SELF_HOSTED:
            buf.write_i32(3)
        if value == FfiProfile.LOCAL:
            buf.write_i32(4)
        if value == FfiProfile.SOVEREIGN:
            buf.write_i32(5)



class _UniffiFfiConverterOptionalString(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiFfiConverterString.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiFfiConverterString.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiFfiConverterString.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")

class _UniffiFfiConverterBoolean:
    @classmethod
    def check_lower(cls, value):
        return not not value

    @classmethod
    def lower(cls, value):
        return 1 if value else 0

    @staticmethod
    def lift(value):
        return value != 0

    @classmethod
    def read(cls, buf):
        return cls.lift(buf.read_u8())

    @classmethod
    def write(cls, value, buf):
        buf.write_u8(value)

