class _UniffiFfiConverterBytes(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        size = buf.read_i32()
        if size < 0:
            raise InternalError("Unexpected negative byte string length")
        return buf.read(size)

    @staticmethod
    def check_lower(value):
        try:
            memoryview(value)
        except TypeError:
            raise TypeError("a bytes-like object is required, not {!r}".format(type(value).__name__))

    @staticmethod
    def write(value, buf):
        buf.write_i32(len(value))
        buf.write(value)






class FfiEvent:
    def __init__(self):
        raise RuntimeError("FfiEvent cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class CONNECTED:
        
        def __init__(self, peer:str, link:FfiLink):
            self.peer = peer
            
            
            self.link = link
            
            
            pass

    
            
            
    
        def __str__(self):
            return "FfiEvent.CONNECTED(peer={}, link={})".format(self.peer, self.link)
        def __eq__(self, other):
            if not isinstance(other, FfiEvent):
                return NotImplemented
            if not other.is_CONNECTED():
                return False
            if self.peer != other.peer:
                return False
            if self.link != other.link:
                return False
            return True

    @dataclass
    class LINK_CHANGED:
        
        def __init__(self, peer:str, link:FfiLink, rtt_ms:int):
            self.peer = peer
            
            
            self.link = link
            
            
            self.rtt_ms = rtt_ms
            
            
            pass

    
            
            
    
        def __str__(self):
            return "FfiEvent.LINK_CHANGED(peer={}, link={}, rtt_ms={})".format(self.peer, self.link, self.rtt_ms)
        def __eq__(self, other):
            if not isinstance(other, FfiEvent):
                return NotImplemented
            if not other.is_LINK_CHANGED():
                return False
            if self.peer != other.peer:
                return False
            if self.link != other.link:
                return False
            if self.rtt_ms != other.rtt_ms:
                return False
            return True

    @dataclass
    class PAIRED:
        
        def __init__(self, peer:str, name:str):
            self.peer = peer
            
            
            self.name = name
            
            
            pass

    
            
            
    
        def __str__(self):
            return "FfiEvent.PAIRED(peer={}, name={})".format(self.peer, self.name)
