# TethersysError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class TethersysError(Exception):
    """
    Flat, so Kotlin gets `TethersysException.Failed(message)` with the text as the
    exception's own message (a `message` field would clash with Throwable.message).
"""
    pass

_UniffiTempTethersysError = TethersysError

class TethersysError:  # type: ignore
    """
    Flat, so Kotlin gets `TethersysException.Failed(message)` with the text as the
    exception's own message (a `message` field would clash with Throwable.message).
"""
    
    class Failed(_UniffiTempTethersysError):
        def __repr__(self):
            return "TethersysError.Failed({})".format(repr(str(self)))
    _UniffiTempTethersysError.Failed = Failed # type: ignore

TethersysError = _UniffiTempTethersysError # type: ignore
del _UniffiTempTethersysError


class _UniffiFfiConverterTypeTethersysError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return TethersysError.Failed(
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, TethersysError.Failed):
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, TethersysError.Failed):
            buf.write_i32(1)


class EventListener():
    """
    Implemented by the app to receive every event.
"""
    
    def on_event(self, event: FfiEvent) -> None:
        raise NotImplementedError

class EventListenerImpl(EventListener):
    """
    Implemented by the app to receive every event.
"""
    
    _handle: ctypes.c_uint64
    
    def __init__(self, *args, **kwargs):
        raise ValueError("This class has no default constructor")

    def __del__(self):
        # In case of partial initialization of instances.
        handle = getattr(self, "_handle", None)
        if handle is not None:
            _uniffi_rust_call(_UniffiLib.uniffi_tethersys_ffi_fn_free_eventlistener, handle)

    def _uniffi_clone_handle(self):
        return _uniffi_rust_call(_UniffiLib.uniffi_tethersys_ffi_fn_clone_eventlistener, self._handle)

    # Used by alternative constructors or any methods which return this type.
    @classmethod
    def _uniffi_make_instance(cls, handle):
        # Lightly yucky way to bypass the usual __init__ logic
        # and just create a new instance with the required handle.
        inst = cls.__new__(cls)
        inst._handle = handle
        return inst
    def on_event(self, event: FfiEvent) -> None:
        
        _UniffiFfiConverterTypeFfiEvent.check_lower(event)
        _uniffi_lowered_args = (
            self._uniffi_clone_handle(),
            _UniffiFfiConverterTypeFfiEvent.lower(event),
        )
        _uniffi_lift_return = lambda val: None
        _uniffi_error_converter = None
        _uniffi_ffi_result = _uniffi_rust_call_with_error(
            _uniffi_error_converter,
            _UniffiLib.uniffi_tethersys_ffi_fn_method_eventlistener_on_event,
            *_uniffi_lowered_args,
        )
        return _uniffi_lift_return(_uniffi_ffi_result)




# Put all the bits inside a class to keep the top-level namespace clean
class _UniffiTraitImplEventListenerImpl:
    # For each method, generate a callback function to pass to Rust

    @_UNIFFI_CALLBACK_INTERFACE_TETHERSYS_FFI_EVENT_LISTENER_METHOD0
    def on_event(
            uniffi_handle,
            event,
            uniffi_out_return,
            uniffi_call_status_ptr,
        ):
        uniffi_obj = _UniffiFfiConverterTypeEventListener._handle_map.get(uniffi_handle)
        def make_call():
            uniffi_args = (_UniffiFfiConverterTypeFfiEvent.lift(event), )
            uniffi_method = uniffi_obj.on_event
            return uniffi_method(*uniffi_args)
        write_return_value = lambda v: None
        _uniffi_trait_interface_call(
                uniffi_call_status_ptr.contents,
                make_call,
                write_return_value,
        )

    @_UNIFFI_CALLBACK_INTERFACE_FREE_TETHERSYS_FFI_EVENT_LISTENER
    def _uniffi_free(uniffi_handle):
        _UniffiFfiConverterTypeEventListener._handle_map.remove(uniffi_handle)

    @_UNIFFI_CALLBACK_INTERFACE_CLONE_TETHERSYS_FFI_EVENT_LISTENER
    def _uniffi_clone(uniffi_handle):
        return _UniffiFfiConverterTypeEventListener._handle_map.clone(uniffi_handle)

    # Generate the FFI VTable.  This has a field for each callback interface method.
    _uniffi_vtable = _UniffiVTableCallbackInterfaceTethersysFfiEventListener(
        _uniffi_free,
        _uniffi_clone,
        on_event,
    )
    # Send Rust a pointer to the VTable.  Note: this means we need to keep the struct alive forever,
    # or else bad things will happen when Rust tries to access it.
    _UniffiLib.uniffi_tethersys_ffi_fn_init_callback_vtable_eventlistener(ctypes.byref(_uniffi_vtable))

class _UniffiFfiConverterTypeEventListener:
    _handle_map = _UniffiHandleMap()

    @staticmethod
    def lift(value: int):
        if (value & 1) == 0:
            # Rust-generated handle, construct a new class that uses the handle to implement the
            # interface
            return EventListenerImpl._uniffi_make_instance(value)
        else:
            # Python-generated handle, get the object from the handle map
            return _UniffiFfiConverterTypeEventListener._handle_map.remove(value)

    @staticmethod
    def check_lower(value: EventListener):
        if not isinstance(value, EventListener):
            raise TypeError("Expected EventListener subclass, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: EventListener):
         if isinstance(value, EventListenerImpl):
            # Rust-implementated object.  Clone the handle and return it
            return value._uniffi_clone_handle()
         else:
            # Python-implementated object, generate a new vtable handle and return that.
            return _UniffiFfiConverterTypeEventListener._handle_map.insert(value)

    @classmethod
    def read(cls, buf: _UniffiRustBuffer):
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: EventListener, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))


