class _UniffiFfiConverterTypeTethersysNode:
    @staticmethod
    def lift(value: int) -> TethersysNode:
        return TethersysNode._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: TethersysNode):
        if not isinstance(value, TethersysNode):
            raise TypeError("Expected TethersysNode instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: TethersysNode) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> TethersysNode:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: TethersysNode, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

